update mall_product
category_id = #{categoryId}, name = #{name}, description = #{description}, price = #{price}, stock = #{stock}, image_url = #{imageUrl}, barcode = #{barcode}, status = #{status}, sort = #{sort}, update_by = #{updateBy}, update_time = #{updateTime}
where product_id = #{productId}

update mall_product
set stock = stock - #{quantity}, update_time = now()
where product_id = #{productId}
  and stock >= #{quantity}
